// ENG-2332: advanced node search drops notes whose nodeTypeId is not a configured type.
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const OPTION = `${MODAL} [role="option"]`;
const TOKEN = "zq2332";

const nodeTypes = ({ client, json, vault }) =>
  client.evaluate(`return app.plugins.plugins[${json(vault.pluginId)}].settings.nodeTypes
    .map((t) => ({ id: t.id, name: t.name, tag: t.tag, imported: !!t.importedFromRid }));`);

const fm = (fields) =>
  `---\n${Object.entries(fields).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join("\n")}\n---\n`;

const waitIndexed = ({ client, json }, path, check) =>
  client.waitFor(`(() => { const f = app.vault.getAbstractFileByPath(${json(path)});
    const c = f && app.metadataCache.getFileCache(f); return !!(c && (${check})); })()`, {
    label: `indexed ${path}`,
  });

const setupNotes = async (ctx) => {
  const types = await nodeTypes(ctx);
  const local = types.find((t) => !t.imported);
  const imported = types.find((t) => t.imported) ?? null;
  const tagged = types.find((t) => t.tag);
  const notes = {
    bogus: await ctx.writeNote(`${TOKEN} bogus type.md`, `${fm({ nodeTypeId: "bogus" })}stray\n`),
    empty: await ctx.writeNote(`${TOKEN} empty type.md`, `${fm({ nodeTypeId: "" })}stray\n`),
