// ENG-2332 before/after: DG_PHASE=before runs against the merge base, after against the fix.
const PHASE = process.env.DG_PHASE === "before" ? "before" : "after";
const LABEL = PHASE === "before" ? "Before" : "After";
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const OPTION = `${MODAL} [role="option"]`;
const TOKEN = "xq7731";
// Fixed folder, so both phases search the same notes regardless of the checked-out branch.
const DIR = "_verify/eng-2332-before-after";

const VERIFY_IMPORTED_TYPE = {
  id: "eng2332-imported-type",
  name: "Imported verify type",
  format: "IVT - {content}",
  created: 0,
  modified: 0,
  importedFromRid: "orn:obsidian.schema:verify/eng2332-imported-type",
};

const fm = (fields) =>
  `---\n${Object.entries(fields).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join("\n")}\n---\n`;

const writeNote = ({ client, json }, name, body) =>
  client.evaluate(`return (async () => {
    const p = ${json(`${DIR}/${name}`)};
    for (const dir of ["_verify", ${json(DIR)}])
      if (!app.vault.getAbstractFileByPath(dir)) await app.vault.createFolder(dir);
    const f = app.vault.getAbstractFileByPath(p);
    if (f) await app.vault.modify(f, ${json(body)}); else await app.vault.create(p, ${json(body)});
    return p;
  })();`);

// In-memory only (never saved), so the modal sees an imported type; teardown removes it.
const addImportedType = ({ client, json, vault }) =>
  client.evaluate(`const s = app.plugins.plugins[${json(vault.pluginId)}].settings;
    if (!s.nodeTypes.some((t) => t.importedFromRid))
      s.nodeTypes = [...s.nodeTypes, ${json(VERIFY_IMPORTED_TYPE)}];
    return true;`);

const removeImportedType = ({ client, json, vault }) =>
  client.evaluate(`const s = app.plugins.plugins[${json(vault.pluginId)}].settings;
    s.nodeTypes = s.nodeTypes.filter((t) => t.id !== ${json(VERIFY_IMPORTED_TYPE.id)});
    return true;`);

const setupNotes = async (ctx) => {
  const { client, json, vault } = ctx;
  await addImportedType(ctx);
  const types = await client.evaluate(`return app.plugins.plugins[${json(vault.pluginId)}].settings.nodeTypes
    .map((t) => ({ id: t.id, tag: t.tag, imported: !!t.importedFromRid }));`);
  const local = types.find((t) => !t.imported);
  const imported = types.find((t) => t.imported);
  const tagged = types.find((t) => t.tag);
  const nodes = [
    await writeNote(ctx, `${TOKEN} bogus type.md`, `${fm({ nodeTypeId: "bogus" })}stray\n`),
    await writeNote(ctx, `${TOKEN} empty type.md`, `${fm({ nodeTypeId: "" })}stray\n`),
    await writeNote(ctx, `${TOKEN} local node.md`, `${fm({ nodeTypeId: local.id })}body\n`),
    await writeNote(
      ctx,
      `${TOKEN} imported node.md`,
      `${fm({ nodeTypeId: imported.id, importedFromRid: "orn:obsidian.note:verify/eng2332" })}body\n`,
    ),
  ];
  const journal = await writeNote(ctx, `${TOKEN} journal.md`, `intro\n${TOKEN} tagged line #${tagged.tag}\n`);
  await client.waitFor(`return (() => {
    const cache = (p) => { const f = app.vault.getAbstractFileByPath(p); return f && app.metadataCache.getFileCache(f); };
    const fmReady = ${json(nodes)}.every((p) => { const c = cache(p); return !!(c && c.frontmatter && "nodeTypeId" in c.frontmatter); });
    const tagReady = !!cache(${json(journal)})?.tags?.length;
    const dc = app.plugins.plugins.datacore?.api;
    const dcReady = !dc?.core?.initialized ||
      ${json(nodes)}.every((p) => new Set(dc.query("@page and exists(nodeTypeId)").map((x) => x.$path)).has(p));
    return fmReady && tagReady && dcReady; })()`, { label: "notes indexed", timeout: 15000 });
  return {};
};

const openAndSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input rendered" });
  await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
  await client.typeText(TOKEN);
  // Debounced query: wait until every row matches it, not just until rows exist.
  await client.waitFor(`return (() => { const els = Array.from(document.querySelectorAll(${json(OPTION)}));
    return els.length > 0 && els.every((el) => el.textContent.includes(${json(TOKEN)})); })()`, {
    label: "query applied",
  });
};

const rows = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(OPTION)})).map((el) => ({
    title: el.querySelector(".dg-search-result-title")?.textContent.trim().replace(${json(`${TOKEN} `)}, ""),
    pill: el.querySelector("[aria-label]")?.getAttribute("aria-label") ?? null,
  }));`);

const describe = (r) => r.map((x) => `${x.title} [${x.pill ?? "no badge"}]`).join(", ");
const find = (r, title) => r.find((x) => x.title === title);

export default [
  {
    name: `${LABEL}: no type filter`,
    input: `notes with nodeTypeId bogus, "", a local type, an imported type; no type filter; query "${TOKEN}"`,
    expected:
      PHASE === "before"
        ? "bug reproduced: bogus note listed with an Unknown type badge"
        : "local and imported nodes listed; bogus and empty-type notes absent; no Unknown type badge",
    setup: setupNotes,
    teardown: removeImportedType,
    run: async (ctx) => {
      await openAndSearch(ctx);
      return rows(ctx);
    },
    expect: (r) => {
      const pass =
        PHASE === "before"
          ? find(r, "bogus type")?.pill === "Unknown type"
          : !!find(r, "local node") &&
            !!find(r, "imported node") &&
            !find(r, "bogus type") &&
            !find(r, "empty type") &&
            !r.some((x) => x.pill === "Unknown type");
      return { pass, actual: describe(r) };
    },
  },
  {
    name: `${LABEL}: show candidate nodes`,
    input: `Display options → Show candidate nodes; query "${TOKEN}"`,
    expected:
      PHASE === "before"
        ? "bug reproduced: bogus note listed next to the tagged-line candidate"
        : "tagged line listed as a candidate; bogus note absent",
    setup: setupNotes,
    teardown: removeImportedType,
    run: async (ctx) => {
      const { client, json } = ctx;
      await openAndSearch(ctx);
      await client.evaluate(`document.querySelector(${json(`${MODAL} [aria-label="Display options"]`)}).click(); return true;`);
      await client.waitFor(`!!document.querySelector('[role="menuitemcheckbox"]')`, { label: "display menu open" });
      await client.evaluate(`document.querySelector('[role="menuitemcheckbox"]').click(); return true;`);
      await client.waitFor(
        `Array.from(document.querySelectorAll(${json(OPTION)})).some((el) => el.textContent.includes("tagged line"))`,
        { label: "candidate row rendered" },
      );
      // Close the menu so the screenshot shows the full result list.
      await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
      return rows(ctx);
    },
    expect: (r) => {
      const candidate = find(r, "tagged line");
      const hasCandidate = !!candidate && (candidate.pill ?? "").endsWith("candidate");
      const pass =
        PHASE === "before"
          ? hasCandidate && !!find(r, "bogus type")
          : hasCandidate && !find(r, "bogus type");
      return { pass, actual: describe(r) };
    },
  },
];
